def dfs(graph, start):
    visited, order = set(), []
    stack = [start]
    while stack:
        v = stack.pop()
        if v in visited:
            continue
        visited.add(v)
        order.append(v)
        for w in graph[v]:
            if w not in visited:
                stack.append(w)
    return order

graph = {"A": ["B", "C"], "B": ["A", "D"],
         "C": ["A", "D"], "D": ["B", "C"]}
```

What does `count_components(graph)` return?

```python
def count_components(graph):
    seen = set()
    count = 0
    def dfs(v):
        seen.add(v)
        for w in graph[v]:
            if w not in seen:
                dfs(w)
    for v in graph:
        if v not in seen:
            count += 1
            dfs(v)
    return count

